'use client';

import { useState, useEffect } from 'react';
import { useOverview } from '@/lib/hooks/use-finance-data';
import { useAppStore } from '@/lib/store/use-app-store';
import { useToast } from '@/hooks/use-toast';
import { UploadModal } from '@/components/upload/upload-modal';
import { QuickStats } from '@/components/dashboard/quick-stats';
import { RecentTransactions } from '@/components/dashboard/recent-transactions';
import { SpendingOverview } from '@/components/dashboard/spending-overview';
import { InsightCards } from '@/components/dashboard/insight-cards';
import { BankWiseChart } from '@/components/dashboard/bank-wise-chart';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Switch } from '@/components/ui/switch';
import { Skeleton } from '@/components/ui/skeleton';
import { Plus, TrendingUp, CreditCard, Wallet, AlertCircle } from 'lucide-react';
import { Tutorial } from '@/components/onboarding/tutorial';
import { EmptyState } from '@/components/ui/empty-state';
import { Alert, AlertTitle, AlertDescription } from '@/components/ui/alert';
import type { Transaction } from '@/types/transaction';

function DashboardContent() {
  const [excludeTransfers, setExcludeTransfers] = useState(false);
  const { data: overview, loading, error, refetch } = useOverview({ exclude_transfers: excludeTransfers });
  const { cards, transactions } = useAppStore();
  const { toast } = useToast();
  const [uploadModalOpen, setUploadModalOpen] = useState(false);
  const [showTutorial, setShowTutorial] = useState(false);
  
  // Show error toast if API fails
  useEffect(() => {
    if (error) {
      toast({
        title: 'Error loading dashboard',
        description: `${error.message}. Falling back to local data.`,
        variant: 'destructive',
      });
    }
  }, [error, toast]);

  // Fallback to Zustand data if API fails
  const hasApiData = overview && overview.transaction_count > 0;
  const hasLocalData = cards.length > 0 || transactions.length > 0;
  const useLocalData = error && hasLocalData && !hasApiData;
  
  // Calculate local data for fallback
  const localTotalSpend = transactions
    .filter((t: Transaction) => t.type === 'debit')
    .reduce((sum: number, t: Transaction) => sum + t.amount, 0);
  const localTransactionCount = transactions.length;
  const localCardCount = cards.length;

  // Open upload modal when upload=true query param is present
  useEffect(() => {
    const shouldUpload = new URLSearchParams(window.location.search).get('upload') === 'true';
    if (shouldUpload) {
      setUploadModalOpen(true);
    }
  }, []);

  // Handle exclude transfers toggle
  const handleExcludeTransfersChange = (checked: boolean) => {
    setExcludeTransfers(checked);
    // Refetch is handled automatically by the hook when excludeTransfers changes
  };

  // Loading state
  if (loading) {
    return (
      <div className="space-y-6 p-6">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <Skeleton className="h-8 w-48" />
            <Skeleton className="h-4 w-64 mt-2" />
          </div>
          <Skeleton className="h-10 w-36" />
        </div>
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
          {[1, 2, 3, 4].map((i) => (
            <Card key={i}>
              <CardHeader className="pb-2">
                <Skeleton className="h-4 w-24" />
              </CardHeader>
              <CardContent>
                <Skeleton className="h-8 w-32" />
                <Skeleton className="h-3 w-48 mt-2" />
              </CardContent>
            </Card>
          ))}
        </div>
        <div className="grid gap-6 lg:grid-cols-7">
          <Card className="lg:col-span-4">
            <CardHeader>
              <Skeleton className="h-6 w-32" />
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                {[1, 2, 3, 4, 5].map((i) => (
                  <Skeleton key={i} className="h-12 w-full" />
                ))}
              </div>
            </CardContent>
          </Card>
          <Card className="lg:col-span-3">
            <CardHeader>
              <Skeleton className="h-6 w-32" />
            </CardHeader>
            <CardContent>
              <Skeleton className="h-[250px] w-full" />
            </CardContent>
          </Card>
        </div>
      </div>
    );
  }

  // Error state with no data
  if (error && !overview && !useLocalData) {
    return (
      <div className="space-y-6 p-6">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold tracking-tight">Dashboard</h1>
            <p className="text-sm text-muted-foreground mt-1">
              Welcome back! Here's your financial overview.
            </p>
          </div>
          <Button onClick={() => setUploadModalOpen(true)}>
            <Plus className="mr-2 h-4 w-4" />
            Upload Statement
          </Button>
        </div>
        <Alert variant="destructive">
          <AlertCircle className="h-4 w-4" />
          <AlertTitle>Error loading data</AlertTitle>
          <AlertDescription>
            {error.message}. Please ensure the API server is running at http://localhost:8000
          </AlertDescription>
        </Alert>
      </div>
    );
  }

  // Determine which data to use
  const displayData = useLocalData ? {
    total_spend_display: `₹${localTotalSpend.toLocaleString('en-IN')}`,
    this_month_display: '₹0',
    last_month_display: '₹0',
    month_change: '0%',
    transaction_count: localTransactionCount,
    card_count: localCardCount,
    monthly_chart: [],
    category_chart: [],
    bank_chart: [],
    recent_transactions: transactions.slice(0, 10),
    behavioral_insights: [],
    above_below_avg: '',
    above_avg_is_bad: false,
    monthly_average_display: '₹0',
  } : overview;

  const hasData = displayData && (displayData.transaction_count > 0 || displayData.recent_transactions.length > 0);

  return (
    <div className="space-y-6 p-6">
      {/* Tutorial */}
      {showTutorial && (
        <Tutorial 
          onComplete={() => setShowTutorial(false)} 
          onSkip={() => setShowTutorial(false)} 
        />
      )}

      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Dashboard</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Welcome back! Here's your financial overview.
          </p>
        </div>
        <div className="flex items-center gap-4">
          {/* Exclude Transfers Toggle */}
          <div className="flex items-center gap-2">
            <span className="text-sm text-muted-foreground">Exclude Transfers</span>
            <Switch
              checked={excludeTransfers}
              onCheckedChange={handleExcludeTransfersChange}
            />
          </div>
          <Button onClick={() => setUploadModalOpen(true)}>
            <Plus className="mr-2 h-4 w-4" />
            Upload Statement
          </Button>
        </div>
      </div>

      {/* Upload Modal */}
      <UploadModal open={uploadModalOpen} onOpenChange={setUploadModalOpen} />

      {!hasData ? (
        // Empty state
        <div className="max-w-2xl mx-auto space-y-6">
          <EmptyState
            icon={<CreditCard className="h-10 w-10" />}
            title="Welcome to Bank Statement Parser"
            description="Get started by uploading your first bank statement. We'll automatically extract your transactions and provide insights into your spending."
            action={{
              label: "Upload Your First Statement",
              onClick: () => setUploadModalOpen(true)
            }}
          />
          
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 text-center">
            <Card>
              <CardContent className="pt-6">
                <CreditCard className="h-8 w-8 mx-auto mb-2 text-primary" />
                <p className="text-sm font-medium">Add Cards</p>
                <p className="text-xs text-muted-foreground mt-1">
                  Upload statements from multiple banks
                </p>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="pt-6">
                <TrendingUp className="h-8 w-8 mx-auto mb-2 text-primary" />
                <p className="text-sm font-medium">Track Spending</p>
                <p className="text-xs text-muted-foreground mt-1">
                  Monitor your expenses by category
                </p>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="pt-6">
                <Wallet className="h-8 w-8 mx-auto mb-2 text-primary" />
                <p className="text-sm font-medium">Save Money</p>
                <p className="text-xs text-muted-foreground mt-1">
                  Identify areas to reduce spending
                </p>
              </CardContent>
            </Card>
          </div>
        </div>
      ) : (
        // Dashboard with data
        <>
          <QuickStats 
            totalSpend={displayData!.total_spend_display}
            thisMonth={displayData!.this_month_display}
            lastMonth={displayData!.last_month_display}
            monthChange={displayData!.month_change}
            transactionCount={displayData!.transaction_count}
            cardCount={displayData!.card_count}
            monthlyChart={displayData!.monthly_chart}
            aboveBelowAvg={displayData!.above_below_avg}
            aboveAvgIsBad={displayData!.above_avg_is_bad}
            monthlyAverage={displayData!.monthly_average_display}
          />
          
          {/* Behavioral Insights */}
          {displayData!.behavioral_insights && displayData!.behavioral_insights.length > 0 && (
            <div className="space-y-4">
              <h2 className="text-lg font-semibold">Insights</h2>
              <InsightCards insights={displayData!.behavioral_insights} />
            </div>
          )}

          <div className="grid gap-6 lg:grid-cols-7">
            <Card className="lg:col-span-4">
              <CardHeader>
                <CardTitle className="text-lg font-semibold">Recent Transactions</CardTitle>
              </CardHeader>
              <CardContent>
                <RecentTransactions transactions={displayData!.recent_transactions.slice(0, 10)} />
              </CardContent>
            </Card>
            
            <div className="lg:col-span-3 space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle className="text-lg font-semibold">Spending by Category</CardTitle>
                </CardHeader>
                <CardContent>
                  <SpendingOverview categoryChart={displayData!.category_chart || []} />
                </CardContent>
              </Card>
              
              {displayData!.bank_chart && displayData!.bank_chart.length > 0 && (
                <Card>
                  <CardHeader>
                    <CardTitle className="text-lg font-semibold">Bank-wise Spend</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <BankWiseChart bankChart={displayData!.bank_chart} />
                  </CardContent>
                </Card>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

export default function DashboardPage() {
  return <DashboardContent />;
}
